import{_ as s,C as a,o as d,c as r,ag as t,E as i}from"./chunks/framework.HG0H2VLS.js";const b=JSON.parse('{"title":"ApiProfileHelp","description":"","frontmatter":{},"headers":[],"relativePath":"cc-templates/api-profile-help.md","filePath":"cc-templates/api-profile-help.md"}'),n={name:"cc-templates/api-profile-help.md"};function c(l,e,p,h,u,g){const o=a("ComponentDemo");return d(),r("div",null,[e[0]||(e[0]=t('<hr><h2 id="title-apiprofilehelp" tabindex="-1">title: ApiProfileHelp <a class="header-anchor" href="#title-apiprofilehelp" aria-label="Permalink to &quot;title: ApiProfileHelp&quot;">​</a></h2><h1 id="apiprofilehelp" tabindex="-1">ApiProfileHelp <a class="header-anchor" href="#apiprofilehelp" aria-label="Permalink to &quot;ApiProfileHelp&quot;">​</a></h1><blockquote><p><code>/control/api-profile-user-help</code> and <code>/control/api-profile-crm-help</code> on v3, <strong>generated</strong> from the classic CFML by `_generate</p></blockquote>',4)),i(o,{src:"/demos/src/cc/templates/ApiProfileHelp/ApiProfileHelp.html"}),e[1]||(e[1]=t('<h2 id="generated-not-hand-written" tabindex="-1">Generated, not hand-written <a class="header-anchor" href="#generated-not-hand-written" aria-label="Permalink to &quot;Generated, not hand-written&quot;">​</a></h2><p><code>_generate.py</code> builds both pages from the classic CFML, so no word is retyped:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 _generate.py --classic &lt;dir with the six sources&gt;</span></span></code></pre></div><p>The sources (<code>APIProfileUserHelp.cfm</code>, <code>APIProfileCRMHelp.cfm</code>, <code>AccountsAction.cfc</code>, <code>UsersAction.cfc</code>, <code>UserAccountsAction.cfc</code>, <code>Subscription.cfc</code>) are read from affino.com&#39;s tree and <strong>not committed</strong>. Fetch them again to regenerate. Edit the generator, not the HTML.</p><p>What it does:</p><ol><li><strong>Resolves the ColdFusion.</strong> <code>#ReplaceNoCase(Application.DB,…)#</code> → <code>Comrz</code>, <code>CGI.HTTP_HOST</code> → <code>www.affino.com</code>. Every <code>Hash()</code> and <code>calculateSignature()</code> is computed with hashlib from a fixed demo instant, <code>2026-10-05T14:30:15.250Z</code> (classic uses <code>now()</code>, so its examples change on every load). <code>createUUID()</code>, <code>Session.IPAddress</code> and <code>CGI.HTTP_USER_AGENT</code> in the tokenLogin example are fixed demo values.</li><li><strong>Reproduces the server-generated field lists.</strong> The CRM page builds 8 lists from each REST action&#39;s <code>getFieldsDef()</code>. The generator evaluates the CFCs&#39; own struct literals with the page&#39;s loop rules (required on create / update, AutoScript, <code>Allowed EQ &quot;all&quot;</code>, Password excluded). An unknown loop shape stops the build rather than guessing. The Lookups section&#39;s subscription statuses come from <code>Subscription.SubscriptionStatusOptions()</code> (14 values).</li><li><strong>Drops <code>&lt;!--- … ---&gt;</code> blocks</strong>, as ColdFusion does. On the CRM page that removes four sections that <strong>never render live</strong>: User Preferences, User Subscriptions (Create / Update), Permissions, Preferences.</li><li><strong>Parses the remaining HTML tolerantly</strong>, with the browser&#39;s implied-end-tag and list-item-scope rules. The classic markup relies on them: unclosed <code>&lt;li&gt;</code>s, and a stray <code>&lt;/li&gt;</code> before Get User&#39;s response body that browsers ignore.</li></ol><h3 id="checks-run-2026-10-05" tabindex="-1">Checks run (2026-10-05) <a class="header-anchor" href="#checks-run-2026-10-05" aria-label="Permalink to &quot;Checks run (2026-10-05)&quot;">​</a></h3><ul><li>hashlib reproduces the classic pages&#39; own stated hashes: the User body MD5 <code>2CD183EC…</code>, the CRM body MD5 <code>6471D2C7…</code>, and the CRM page&#39;s full SHA-512 example signature <code>45FCF7D9…</code>.</li><li><strong>Word-for-word diff</strong> of each resolved classic page against the generated content: nothing missing, nothing extra, apart from the label colons and &quot;Description:&quot; prefixes the layout replaces. The first run caught the stray-<code>&lt;/li&gt;</code> body above being dropped; it was fixed and re-checked.</li><li>Endpoints: User 12, CRM 19 (the CRM page&#39;s 24 headings, less the 5 inside the comment).</li></ul><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>From</th><th>Notes</th></tr></thead><tbody><tr><td>On this page</td><td>RecordSection + DropdownItem-style links</td><td>Sticky rail beside the sections (240px, <code>size-4</code>); endpoint count Badges; scroll-spy marks the section in view (<code>aria-current</code>). Hover is the row background only: colour and underline are reset against base.css <code>a:hover</code> (designer, 2026-10-05)</td></tr><tr><td>On this page (narrow)</td><td>DS Select (<code>sel</code>, Select.js)</td><td>Below 1023 (<code>cs-page</code>) the rail is replaced by ONE sticky Select that names the section in view and jumps to any other (designer, 2026-10-05: wrapping 13 links above the content was neither efficient nor clear). Each option and the closed trigger carry the rail&#39;s endpoint-count chip (designer, 2026-10-05); rows reserve the tick&#39;s width so the chips line up. Scroll-spy keeps the value, chip and tick in step. Pinned, it sits on a page-ground backdrop (<code>--cc-ui-primary-bg</code>) so content cannot show through the 24px band above it (added with the test tools, 2026-10-05)</td></tr><tr><td>Sections</td><td>RecordSection (<code>--full</code> in full width)</td><td>One card per classic <code>&lt;h2&gt;</code>; the intro card carries the <code>&lt;h1&gt;</code> (&quot;User API version 1&quot; / &quot;CRM API version 1&quot;)</td></tr><tr><td>Endpoint</td><td>An article per endpoint, divided by <code>border-secondary</code></td><td>Name (CRM) as a subhead, then method Badge (GET <code>info</code>, POST <code>success</code>, PUT <code>warning</code>, DELETE <code>danger</code>) + path</td></tr><tr><td>Example rows</td><td>key: value grid (key 160px, <code>size-2</code>)</td><td>Request / Response groups; Header&#39;s rows nest in the value column. Stack at RecordSection&#39;s 559, where FieldRow&#39;s rows stack. Empty values show a muted &quot;—&quot;</td></tr><tr><td>Code</td><td>AutoAnswers&#39; inline code style, token for token</td><td>Title font at medium weight on <code>surface-secondary</code> (there is no monospace token). The worked examples (signature calculation, error responses) are a wrapped code block, one line per classic <code>&lt;p&gt;</code></td></tr><tr><td>Parameter names</td><td>the same code style, tighter padding</td><td>Classic&#39;s <code>&lt;b&gt;</code></td></tr><tr><td>Lookups links</td><td>brand text link + external-link icon</td><td>Open the CC screen in a new tab, as classic does</td></tr></tbody></table><p>No new tokens. Text is FieldRow&#39;s value style; subheads are FieldRow&#39;s label style, with endpoint names one step up (Contract Analysis&#39;s table title).</p><h2 id="responsive" tabindex="-1">Responsive <a class="header-anchor" href="#responsive" aria-label="Permalink to &quot;Responsive&quot;">​</a></h2><p>Grid → one column below 1023 (<code>cs-page</code>, on the inner <code>__layout</code>: the page is the container and cannot query itself, which the first pass got wrong), with the sticky Select in place of the rail. Example rows stack at RecordSection 559. Measured at 390: both pages 390/390, no element past the edge.</p><h2 id="backend-todo-backend-apiprofilehelp" tabindex="-1">Backend (<code>TODO(backend:ApiProfileHelp)</code>) <a class="header-anchor" href="#backend-todo-backend-apiprofilehelp" aria-label="Permalink to &quot;Backend (`TODO(backend:ApiProfileHelp)`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>id</th><th>What</th></tr></thead><tbody><tr><td><code>api-help-render</code></td><td>Render server-side with the site&#39;s own name and host and a live timestamp, so each example MD5 / Signature is recomputed per request, as classic does. The field lists come from each action&#39;s <code>getFieldsDef()</code> live. The commented-out sections stay out unless someone revives them on purpose</td></tr><tr><td><code>api-help-source-errors</code></td><td>Not fixed: the content is carried over as written. Worth a pass by whoever owns the API docs: &quot;sucessful&quot;, &quot;usres&quot;, &quot;Subriptions&quot;, &quot;sting&quot;, &quot;greater that&quot;; &quot;not-not-required&quot; (Notes, Update User Subscription, which is commented out anyway); Get User Subscriptions&#39; example signs a POST to <code>?subscriptions</code> while the request is a GET to <code>/subscriptions</code>; Update User Subscription&#39;s example URL <code>/crm/v1?subscriptions/34</code>; List Preferences&#39; example calls <code>/permissions</code></td></tr></tbody></table>',15))])}const f=s(n,[["render",c]]);export{b as __pageData,f as default};
